<script>
const tg = window.Telegram && window.Telegram.WebApp;
if (tg) { tg.ready(); tg.expand(); }
const DATA_BASE_URL = 'https://osbbcopilot.app.n8n.cloud/webhook/demo-archi-owner-view-data';
let DATA = null;
let state = { view: 'dashboard', group: null, idx: 0, tab: 'rent' };
const ICON = { red: '🔴', yellow: '🟡', green: '🟢' };
function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function row(label, value, cls){ return '<div class="metric' + (cls ? ' ' + cls : '') + '"><span class="label">' + label + '</span><span class="value">' + value + '</span></div>'; }
function hint(text){ return '<div class="hint">' + text + '</div>'; }
function plProj(n){ var n10=n%10, n100=n%100; if(n10===1&&n100!==11) return 'проєкт'; if(n10>=2&&n10<=4&&(n100<12||n100>14)) return 'проєкти'; return 'проєктів'; }
const TAB_DEFS = [ {id:'rent', label:'Рентабельність'}, {id:'profit', label:'Прибуток'}, {id:'volume', label:'Акти і гроші'}, {id:'etc', label:'Години'}, {id:'evm', label:'EVM'} ];
function renderDashboard(tab){
  if (tab) state.tab = tab;
  const activeTab = state.tab || 'rent';
  const v = DATA.views[activeTab];
  const c = DATA.counts || {red:0,yellow:0,green:0};
  const pfc = DATA.pfc || {};
  const pfcHtml = '<div class="section-title">План — факт — прогноз</div><div class="block">' +
    row('Проєкти', (pfc.planProjects||0) + ' / ' + (pfc.factProjects||0) + ' / ' + (pfc.forecastProjects||0)) +
    row('Workload, год', (pfc.planHours||0).toLocaleString('uk-UA') + ' / ' + (pfc.factHours||0).toLocaleString('uk-UA') + ' / ' + (pfc.forecastHours||0).toLocaleString('uk-UA')) +
  '</div>' +
  '<div class="section-title">Комерційні пропозиції (КП)</div><div class="block">' +
    row('Надіслано цього місяця', (pfc.kpMonthSent||0) + ' ' + plProj(pfc.kpMonthSent||0)) +
    row('Очікувано договорів (≈' + (pfc.kpConversionPct||0) + '%)', '≈' + (pfc.kpProjectedContracts||0)) +
  '</div>' +
  '<div class="hint">Орієнтовна конверсія (припущення, не виміряний факт). Лічильник: команда «КП: N» в чаті. Повний облік по кожному КП — у беклозі.</div>';
  const tabsHtml = TAB_DEFS.map(function(t){ return '<button class="tab' + (t.id===activeTab?' active':'') + '" data-tab="' + t.id + '">' + t.label + '</button>'; }).join('');
