      var bCls = (bDays !== null && bDays >= BLOCK_RED_DAYS) ? 'red' : 'yellow';
      var typesText = bl.types.map(function(t){ return BLOCK_LABEL[t] || t; }).join('; ');
      blocker = { cls: bCls, days: bDays, sinceFmt: fmtDate(bl.since), typesText: typesText, need: bl.need || null, etcTotal: etcTotal,
        endPlanFmt: endPlan ? fmtDate(endPlan) : '—', weeksLeftFmt: weeksLeft === null ? '—' : (weeksLeft > 0 ? (Math.round(weeksLeft * 10) / 10) + ' тиж.' : 'дедлайн минув'),
        paceFmt: pace === null ? (weeksLeft !== null && weeksLeft <= 0 ? 'дедлайн Р вже минув' : '—') : pace + ' год/тиж.' };
      signals.push({ c: bCls, b: true, t: 'Проєкт стоїть' + (bDays !== null ? ' ' + bDays + ' дн. (з ' + fmtDate(bl.since) + ')' : '') + ': ' + typesText });
    }
    wr = { week: fmtDate(row['wr_week']), stages: stages, actProb: toNum(row['wr_act_prob']), docProb: docProb, docCls: docCls,
           problems: problems, help: help, plans: row['wr_plans'] ? String(row['wr_plans']).split('\n').filter(Boolean) : [] };
  } else {
    if (!noFc) signals.push({c:'yellow', t:'ПМ ще не подавав тижневий звіт'});
  }

  var lastFcFmt = null;
  if (noFc) {
    var fcPct = toNum(row['forecast_confirmed_pct']);
    if (fcPct !== null) lastFcFmt = fmtPct(fcPct) + (row['forecast_confirmed_week'] ? ' (звіт за ' + fmtDate(row['forecast_confirmed_week']) + ')' : '');
    var missSt = [];
    if (row['wr_week']) {
      var rd2 = obj(row['wr_readiness']), et2 = obj(row['wr_etc']);
      missSt = STAGES.filter(function(s){ return !(Number(rd2[s]) >= 100) && (et2[s] === undefined || et2[s] === null); });
    }
    var why = !row['wr_week'] ? 'ПМ не подав жодного тижневого звіту' : ('ПМ не дав ETC по ' + (missSt.length ? missSt.join(', ') : 'стадіях'));
    signals.push({c:'red', t:'Прогноз відсутній: ' + why + (lastFcFmt ? '. Останній підтверджений прогноз рентабельності ' + lastFcFmt : '')});
  }
  signals.sort(function(a,b){ return ((a.b?0:2) + (a.c==='red'?0:1)) - ((b.b?0:2) + (b.c==='red'?0:1)); });
  var reds = signals.filter(function(s){ return s.c==='red'; }).length;
  var yellows = signals.length - reds;
  projects.push({
    id: id, name: id,
    status: reds ? 'red' : (yellows ? 'yellow' : 'green'), reds: reds, yellows: yellows, signals: signals, cls: cls, wr: wr, blocker: blocker,
    contract: toNum(row['contract_amount']), contractFmt: fmtUAH(toNum(row['contract_amount'])),
    rentPlan: rentP !== null ? rentP/100 : null, rentPlanFmt: fmtPct(rentP),
    noForecast: noFc, lastConfirmedForecast: lastFcFmt,
    rentForecast: noFc ? null : rentF/100, rentForecastFmt: noFc ? ('🔴 Прогноз відсутній' + (lastFcFmt ? ' (останній: ' + lastFcFmt + ')' : '')) : fmtPct(rentF),
    profitPlan: profitP, profitPlanFmt: fmtUAH(profitP),
    profitForecast: noFc ? null : profitF, profitForecastFmt: noFc ? '🔴 Прогноз відсутній' : fmtUAH(profitF),
    executedWorkFmt: fmtUAH(Q), receivedFmt: fmtUAH(P), actsFmt: fmtUAH(S),
    moneyToCompleteTeamFmt: fmtUAH(toNum(row['money_to_completion_team'])),
    moneyToCompleteSubFmt: fmtUAH(toNum(row['money_to_completion_subcontract'])),
    etcPlanFmt: fmtHrs(etcPlan), etcForecastFmt: noFc ? '🔴 Не подано ПМом' : fmtHrs(etcF), etc: etcF,
    cpi: cpi, cpiFmt: fmtRatio(cpi),
    planHrs: toNum(row['planned_hours']), factHrs: toNum(row['actual_hours']),
    rawQ: Q, rawS: S, rawP: P, rawEtcPlan: etcPlan, rawEtcForecast: etcF
  });
});

function groupBy(fn){ var g = {critical:[], attention:[], normal:[]}; projects.forEach(function(p){ var r = fn(p); if (r) g[r[0]].push({ id:p.id, name:p.name, value:r[1] }); }); return g; }
function mk(defs, g){ return defs.map(function(d){ return Object.assign({}, d, { count: g[d.id].length, value: g[d.id].length }); }); }

const rentG = groupBy(function(p){ var c = p.cls.rent; return [c==='red'?'critical':(c==='yellow'?'attention':'normal'), p.noForecast ? 'прогноз відсутній' : p.rentForecastFmt]; });
const rentDefs = [
  {id:'critical', label:'Збиткові', sub:'прогноз рентабельності < 0% або прогноз відсутній (ПМ не дав ETC)', color:'red'},
  {id:'attention', label:'Під загрозою', sub:'прогноз нижче плану з Кошторису на ' + RENT_DROP_PP + ' п.п. і більше', color:'yellow'},
  {id:'normal', label:'Норма', sub:'прогноз у межах плану з Кошторису', color:'green'}
];
const profitG = groupBy(function(p){ var c = p.cls.profit; return [c==='red'?'critical':(c==='yellow'?'attention':'normal'), p.noForecast ? 'прогноз відсутній' : p.profitForecastFmt]; });
const profitDefs = [
  {id:'critical', label:'Збиток', sub:'прибуток прогноз < 0, відхилення ≥ ' + PROFIT_RED_PCT + '% або прогноз відсутній', color:'red'},
  {id:'attention', label:'Відхилення ≥ ' + PROFIT_YELLOW_PCT + '%', sub:'прибуток нижче плану', color:'yellow'},
  {id:'normal', label:'Норма', sub:'відхилення < ' + PROFIT_YELLOW_PCT + '% від плану', color:'green'}
];
const volG = groupBy(function(p){ var c = p.cls.received || 'green'; return [c==='red'?'critical':(c==='yellow'?'attention':'normal'), fmtUAH(Math.max(0,(p.rawQ||0)-(p.rawP||0)))]; });
const volDefs = [
  {id:'critical', label:'Багато роботи без оплати', sub:'не оплачено > ' + (UNPAID_RED*100) + '% контракту', color:'red'},
  {id:'attention', label:'Робота випереджає оплату', sub:'не оплачено ' + (UNPAID_YELLOW*100) + '–' + (UNPAID_RED*100) + '% контракту', color:'yellow'},
  {id:'normal', label:'Оплата встигає за роботою', sub:'не оплачено ≤ ' + (UNPAID_YELLOW*100) + '% контракту', color:'green'}
];
const etcG = groupBy(function(p){ var c = p.cls.etc || 'green'; return [c==='red'?'critical':(c==='yellow'?'attention':'normal'), p.noForecast ? 'ETC не подано' : fmtHrs((p.rawEtcForecast||0)-(p.rawEtcPlan||0))]; });
const etcDefs = [
  {id:'critical', label:'Годин треба на ' + Math.round(ETC_RED*100) + '%+ більше плану або ETC не подано', color:'red'},
  {id:'attention', label:'На ' + Math.round(ETC_YELLOW*100) + '–' + Math.round(ETC_RED*100) + '% більше плану', color:'yellow'},
  {id:'normal', label:'У межах плану', color:'green'}
];
const evmG = groupBy(function(p){ if (p.cpi === null) return null; var c = p.cls.cpi; return [c==='red'?'critical':(c==='yellow'?'attention':'normal'), p.cpiFmt]; });
const evmDefs = [
  {id:'critical', label:'CPI < ' + fmtRatio(CPI_RED) + ' — перевитрата', color:'red'},
  {id:'attention', label:'CPI ' + fmtRatio(CPI_RED) + '–' + fmtRatio(CPI_YELLOW) + ' — на межі', color:'yellow'},
  {id:'normal', label:'CPI ≥ ' + fmtRatio(CPI_YELLOW) + ' — норма', color:'green'}
];

const fcProjects = projects.filter(function(p){ return !p.noForecast; });
const noFcCount = projects.length - fcProjects.length;
const avgRentForecast = fcProjects.length ? fcProjects.reduce(function(s,p){ return s+p.rentForecast; }, 0) / fcProjects.length : 0;
const avgRentPlan = fcProjects.length ? fcProjects.reduce(function(s,p){ return s+(p.rentPlan||0); }, 0) / fcProjects.length : 0;
const totalProfitPlan = fcProjects.reduce(function(s,p){ return s+(p.profitPlan||0); }, 0);
const totalProfitForecast = fcProjects.reduce(function(s,p){ return s+(p.profitForecast||0); }, 0);
const totalContract = projects.reduce(function(s,p){ return s+(p.contract||0); }, 0);
const volumeGapSum = projects.map(function(p){ return (p.rawQ||0) - (p.rawP||0); }).filter(function(v){ return v>0; }).reduce(function(s,v){ return s+v; }, 0);
const etcGapValues = fcProjects.map(function(p){ return (p.rawEtcForecast||0) - (p.rawEtcPlan||0); });
const etcGapAvg = etcGapValues.length ? etcGapValues.reduce(function(s,v){ return s+v; },0)/etcGapValues.length : 0;
const cpiValues = projects.map(function(p){ return p.cpi; }).filter(function(v){ return v!==null && v!==undefined; });
const cpiAvg = cpiValues.length ? cpiValues.reduce(function(s,v){ return s+v; },0)/cpiValues.length : 0;
function heroCls(v, red, yellow, higherIsBetter){ if (v===null) return ''; return higherIsBetter ? (v < red ? 'red' : (v < yellow ? 'yellow' : 'green')) : (v > red ? 'red' : (v > yellow ? 'yellow' : 'green')); }

const views = {
  rent: { title: 'Рентабельність', heroL: { label: 'План (середня' + (noFcCount ? ', тільки проєкти з прогнозом' : '') + ')', value: (avgRentPlan*100).toFixed(0)+'%' }, heroR: { label: 'Прогноз (середня)' + (noFcCount ? ' · без прогнозу: ' + noFcCount : ''), value: (avgRentForecast*100).toFixed(0)+'%', cls: (noFcCount > 0 || avgRentForecast < 0 || (avgRentPlan - avgRentForecast) * 100 >= RENT_DROP_PP_RED) ? 'red' : ((avgRentPlan - avgRentForecast) * 100 >= RENT_DROP_PP ? 'yellow' : 'green') }, groups: mk(rentDefs, rentG), groupProjects: rentG },
  profit: { title: 'Прибуток', heroL: { label: 'План', value: fmtUAH(totalProfitPlan) }, heroR: { label: 'Прогноз' + (noFcCount ? ' · без прогнозу: ' + noFcCount : ''), value: fmtUAH(totalProfitForecast), cls: (function(){ if (noFcCount > 0 || totalProfitForecast < 0) return 'red'; var dev = totalProfitPlan ? (totalProfitPlan-totalProfitForecast)/totalProfitPlan*100 : null; if (dev !== null && dev >= PROFIT_RED_PCT) return 'red'; if (dev !== null && dev >= PROFIT_YELLOW_PCT) return 'yellow'; return 'green'; })() }, groups: mk(profitDefs, profitG), groupProjects: profitG },
  volume: { title: 'Роботи, акти, гроші', heroL: { label: 'Виконано і не оплачено', value: fmtUAH(volumeGapSum), cls: volumeGapSum > 0 ? 'yellow' : 'green' }, heroR: { label: 'Проєктів з розривом', value: volG.critical.length + volG.attention.length }, groups: mk(volDefs, volG), groupProjects: volG },
  etc: { title: 'Скільки годин ще потрібно', heroL: { label: 'Середній розрив до плану', value: fmtHrs(etcGapAvg), cls: etcGapAvg > 0 ? 'yellow' : 'green' }, heroR: { label: 'Проєктів з перевищенням', value: etcG.critical.length + etcG.attention.length }, groups: mk(etcDefs, etcG), groupProjects: etcG },
  evm: { title: 'EVM', heroL: { label: 'Середній CPI', value: fmtRatio(cpiAvg), cls: heroCls(cpiAvg, CPI_RED, CPI_YELLOW, true) }, heroR: { label: 'Проєктів з CPI < ' + fmtRatio(CPI_RED), value: evmG.critical.length }, groups: mk(evmDefs, evmG), groupProjects: evmG }
};

const attention = projects.filter(function(p){ return p.status !== 'green'; })
  .sort(function(a,b){ return ((b.blocker?1:0) - (a.blocker?1:0)) || (b.reds - a.reds) || (b.yellows - a.yellows); })
  .map(function(p){ return { id: p.id, status: p.status, blocked: !!p.blocker, reds: p.reds, yellows: p.yellows, top: p.signals.length ? p.signals[0].t : '' }; });

// Факт = є надходження коштів (аванс); Прогноз = є договір (сума або файл), незалежно від того чи вже внесено кошторис (рішення власника 03.10.2026)
const pfcFactProjects = metricsRows.filter(function(r){ return (toNum(r['money_received'])||0) > 0; }).length;
const pfcForecastProjects = metricsRows.filter(function(r){ return toNum(r['contract_amount']) !== null || !!r['contract_file_url']; }).length;
const pfcFactHours = Math.round(metricsRows.reduce(function(s,r){ return s + (((toNum(r['money_received'])||0) > 0) ? (toNum(r['actual_hours'])||0) : 0); }, 0));
const pfcForecastHours = Math.round(metricsRows.reduce(function(s,r){ var hasContract = toNum(r['contract_amount']) !== null || !!r['contract_file_url']; return s + (hasContract ? ((toNum(r['actual_hours'])||0) + (toNum(r['etc_forecast_total_hours'])||0)) : 0); }, 0));

// КП — окрема воронка, поки без окремої таблиці по кожному КП — лише місячна лічилка (kp_log) з бота ('КП: N')
let kpMonthSent = 0;
try { kpMonthSent = Number((($('Fetch KP Log Sum (MiniApp)').first() || {}).json || {}).kp_month) || 0; } catch(e1) {
  try { kpMonthSent = Number((($('Fetch KP Log Sum (Chat)').first() || {}).json || {}).kp_month) || 0; } catch(e2) { kpMonthSent = 0; }
}
const KP_CONVERSION_PCT = 25; // орієнтовна конверсія КП→Договір — припущення власника (03.10.2026), не виміряний факт
const kpProjectedContracts = Math.round(kpMonthSent * KP_CONVERSION_PCT / 100);

const data = {
  asOf: new Date().toLocaleDateString('uk-UA'),
  projects: projects, attention: attention,
  counts: { red: projects.filter(function(p){ return p.status==='red'; }).length, yellow: projects.filter(function(p){ return p.status==='yellow'; }).length, green: projects.filter(function(p){ return p.status==='green'; }).length, blocked: projects.filter(function(p){ return !!p.blocker; }).length },
  totalContract: totalContract, totalContractFmt: fmtUAH(totalContract),
  pfc: { planProjects: 100, planHours: 10000, factProjects: pfcFactProjects, forecastProjects: pfcForecastProjects, factHours: pfcFactHours, forecastHours: pfcForecastHours, kpMonthSent: kpMonthSent, kpConversionPct: KP_CONVERSION_PCT, kpProjectedContracts: kpProjectedContracts },
  rules: { RENT_DROP_PP: RENT_DROP_PP, RENT_DROP_PP_RED: RENT_DROP_PP_RED, PROFIT_YELLOW_PCT: PROFIT_YELLOW_PCT, PROFIT_RED_PCT: PROFIT_RED_PCT, CPI_RED: CPI_RED, CPI_YELLOW: CPI_YELLOW, ETC_RED: ETC_RED, ETC_YELLOW: ETC_YELLOW, UNPAID_YELLOW: UNPAID_YELLOW, UNPAID_RED: UNPAID_RED, SLIP_RED_DAYS: SLIP_RED_DAYS, BLOCK_RED_DAYS: BLOCK_RED_DAYS },
  views: views
};
return [{ json: data }];

function toNum(v){
  if (v === null || v === undefined || v === '' || v === '—') return null;
  if (typeof v === 'number') return v;
  var n = parseFloat(String(v).replace(/\s/g,'').replace(',', '.'));
  return isNaN(n) ? null : n;
}
function fmtUAH(v){ if (v===null||v===undefined) return '—'; return Math.round(v).toLocaleString('uk-UA') + ' грн'; }
function fmtPct(v){ if (v===null||v===undefined) return '—'; return v.toFixed(1).replace('.',',') + '%'; }
function fmtRatio(v){ if (v===null||v===undefined) return '—'; return v.toFixed(2).replace('.',','); }

// Джерело — project_metrics (план з Кошторису + факт + звіт ПМа), без Google Sheets
const rows = $input.all().map(function(i){ return i.json; });
const lines = [];
rows.forEach(function(row){
  var id = String(row['project_id'] || '').trim();
  if (!id) return;
  var etc = toNum(row['etc_forecast_total_hours']);
  lines.push(id + ': Контракт ' + fmtUAH(toNum(row['contract_amount'])) + ' | Рент ' + fmtPct(toNum(row['profitability_forecast_pct'])) + ' | Прибуток ' + fmtUAH(toNum(row['profit_forecast'])) + ' | ETC ' + (etc!==null ? (Math.round(etc*10)/10) + ' год' : '—') + ' | CPI ' + fmtRatio(toNum(row['cpi_classic_evm'])));
});
const text = 'Портфель DEMO (' + lines.length + ' проектів):' + String.fromCharCode(10,10) + lines.join(String.fromCharCode(10));
return [{ json: { statusText: text, chat_id: $('Telegram Trigger').item.json.message.chat.id } }];

