parameters.jsCode:
const msg = ($('Telegram Trigger').item.json.message) || {};
const text = (msg.text || '').trim();
const modeRow = ($input.first() && $input.first().json) || {};
const mode = modeRow.mode || 'idle';
const hasAudio = !!msg.voice;
const hasPhoto = !!msg.photo;
const hasDocument = !!msg.document;
const lower = text.toLowerCase();
const normalized = lower.replace(/[^\p{L}\d\s\/-]/gu, '').trim();
const isOwnerViewLike = /^\/(project|owner_view|status|all_projects|weekly_render|weekly_history)$/i.test(text) || /(огляд|owner|меню|щотижнев|тижнева історія)/i.test(text);
const isWrCommand = /^(\/weekly|\/start|новий звіт|start|старт)$/.test(normalized) || /^новий$/.test(normalized) || /^про[єе]кт\s+[a-zа-яіїєґ0-9_-]+$/.test(normalized) || /^імпорт\s+[a-zа-яіїєґ0-9_-]+$/.test(normalized) || /^зустріч\s+[a-zа-яіїєґ0-9_-]+$/.test(normalized) || /^додати\s+.+/.test(normalized) || /^(чернетка|відправити)$/.test(normalized) || /^фінал$/.test(normalized) || /^скасувати$/.test(normalized) || /^статус\s*звіт(ів)?$/.test(normalized) || /^довідник$/.test(normalized) || /^назад$/.test(normalized) || /^кошторис\s+[a-zа-яіїєґ0-9_-]+$/.test(normalized) || /^затвердити$/.test(normalized) || /^(тижневий звіт|години і гроші|зустріч|кошторис)$/.test(normalized);
const inWrSession = (mode === 'weekly_report' || mode === 'weekly_reference' || mode === 'import_log' || mode === 'meeting_log' || mode === 'koshtorys_preview');
const isWrFlow = Boolean(isWrCommand || (inWrSession && !isOwnerViewLike && (hasAudio || hasPhoto || hasDocument || text.length > 0)));
return [{ json: { is_wr_flow: isWrFlow, mode: mode, project_id: modeRow.project_id || null } }];

const modeRow = ($('WR: Read Mode').first() && $('WR: Read Mode').first().json) || {};
const currentMode = modeRow.mode || 'idle';
const currentProject = modeRow.project_id || null;
const item = $input.first();
const rawText = String(item.json.raw_text || '').trim();
const lower = rawText.toLowerCase();
const normalized = lower.replace(/[^\p{L}\d\s\/-]/gu, '').trim();

if (/^(\/weekly|\/start|новий звіт|start|старт)$/.test(normalized)) { return [{ json: { execution_mode: 'clear_context', payload: '', project_id: null } }]; }

// Меню: вибір проєкту кнопкою (дія → клавіатура проєктів)
const PICK = { 'тижневий звіт': '📝 проєкт', 'години і гроші': '⏱ імпорт', 'зустріч': '🤝 зустріч', 'кошторис': '📐 кошторис', 'договір': '📄 договір' };
if (PICK[normalized]) { return [{ json: { execution_mode: 'pick_project', payload: PICK[normalized], project_id: currentProject } }]; }

// Потік А: завантаження Кошторису (доступ — список команди, як у Mini App)
const ALLOWED = ['304884647'];
const fromId = String(((($('Telegram Trigger').first().json.message) || {}).from || {}).id || '');
const koshMatch = normalized.match(/^кошторис\s+([a-zа-яіїєґ0-9_-]+)$/);
if (koshMatch) {
  if (ALLOWED.indexOf(fromId) < 0) { return [{ json: { execution_mode: 'koshtorys_forbidden', payload: '', project_id: currentProject } }]; }
  return [{ json: { execution_mode: 'koshtorys_preview', mode: 'preview', payload: '', project_id: koshMatch[1].toUpperCase(), telegram_user_id: fromId } }];
}

const projMatch = normalized.match(/^про[єе]кт\s+([a-zа-яіїєґ0-9_-]+)$/);
if (projMatch) { return [{ json: { execution_mode: 'set_project', payload: projMatch[1].toUpperCase(), project_id: projMatch[1].toUpperCase() } }]; }

const importMatch = normalized.match(/^імпорт\s+([a-zа-яіїєґ0-9_-]+)$/);
if (importMatch) { return [{ json: { execution_mode: 'set_import_project', payload: importMatch[1].toUpperCase(), project_id: importMatch[1].toUpperCase() } }]; }

const meetingMatch = normalized.match(/^зустріч\s+([a-zа-яіїєґ0-9_-]+)$/);
if (meetingMatch) { return [{ json: { execution_mode: 'set_meeting_project', payload: meetingMatch[1].toUpperCase(), project_id: meetingMatch[1].toUpperCase() } }]; }

if (/^скасувати$/.test(normalized)) { return [{ json: { execution_mode: 'clear_context', payload: '', project_id: null } }]; }
if (/^назад$/.test(normalized)) { return [{ json: { execution_mode: 'clear_context', payload: '', project_id: null } }]; }
if (/^статус\s*звіт(ів)?$/.test(normalized)) { return [{ json: { execution_mode: 'status', payload: '', project_id: currentProject } }]; }
if (/^довідник$/.test(normalized)) { return [{ json: { execution_mode: 'set_reference_mode', payload: '', project_id: currentProject } }]; }

if (currentMode === 'koshtorys_preview') {
  if (/^затвердити$/.test(normalized)) {
    if (ALLOWED.indexOf(fromId) < 0) { return [{ json: { execution_mode: 'koshtorys_forbidden', payload: '', project_id: currentProject } }]; }
    return [{ json: { execution_mode: 'koshtorys_commit', mode: 'commit', payload: '', project_id: currentProject, telegram_user_id: fromId } }];
  }
  return [{ json: { execution_mode: 'koshtorys_hint', payload: '', project_id: currentProject } }];
}

if (!currentProject) { return [{ json: { execution_mode: 'need_project', payload: '', project_id: null } }]; }

const isNew = /^новий$/.test(normalized);
const isDraft = /^(чернетка|відправити)$/.test(normalized);
const isFinal = /^фінал$/.test(normalized);

if (currentMode === 'meeting_log') {
  if (isNew) { return [{ json: { execution_mode: 'reset_meeting_draft', payload: '', project_id: currentProject } }]; }
  if (isDraft) { return [{ json: { execution_mode: 'show_meeting_draft', payload: 'Покажи поточну чернетку журналу зустрічей — усі накопичені за сесію рішення/дії, нічого нового не додавай.', project_id: currentProject } }]; }
  if (isFinal) { return [{ json: { execution_mode: 'generate_meeting_final', payload: 'Зведи всі накопичені за сесію рішення/дії у фінальний список.', project_id: currentProject } }]; }
  return [{ json: { execution_mode: 'process_meeting_transcript', payload: rawText, project_id: currentProject } }];
}

if (currentMode === 'import_log') {
  if (isNew) { return [{ json: { execution_mode: 'reset_import_draft', payload: '', project_id: currentProject } }]; }
  if (isDraft) { return [{ json: { execution_mode: 'show_import_draft', payload: 'Покажи поточну чернетку імпорту Time_Log/Money_Log.', project_id: currentProject } }]; }
  if (isFinal) { return [{ json: { execution_mode: 'generate_import_final', payload: 'Сформуй фінальний імпорт Time_Log/Money_Log і виведи структуровані рядки.', project_id: currentProject } }]; }
  return [{ json: { execution_mode: 'process_import_data', payload: rawText, project_id: currentProject } }];
}

if (isNew) { return [{ json: { execution_mode: 'reset_wr_draft', payload: '', project_id: currentProject } }]; }
if (isDraft) { return [{ json: { execution_mode: 'show_draft', payload: 'Покажи поточну чернетку тижневого звіту у повній фіксованій структурі.', project_id: currentProject } }]; }
if (isFinal) { return [{ json: { execution_mode: 'generate_final', payload: 'Сформуй фінальний тижневий звіт у повній фіксованій структурі.', project_id: currentProject } }]; }
const addMatch = rawText.match(/^додати\s+(.+)/i);
const payloadText = addMatch ? addMatch[1] : rawText;
return [{ json: { execution_mode: 'process_data', payload: payloadText, project_id: currentProject } }];

// Джерело — wr_weekly_snapshots (база), не Google Sheets. Список проєктів — з project_metrics.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r.project_id; });
const week = $now.startOf('week');
const lines = rows.map(function (r) {
  const blocked = Array.isArray(r.blocker_types) && r.blocker_types.length > 0;
  return (r.reported ? '✅ ' : '⬜ ') + r.project_id + (blocked ? ' ⛔ стоїть' : '') + (r.gap ? ' ⚖️ розбіжність готовності' : '');
});
const done = rows.filter(function (r) { return r.reported; }).length;
const text = 'Статус тижневих звітів (тиждень з ' + week.toFormat('dd.MM.yyyy') + '): ' + done + ' з ' + rows.length + '\n\n' + lines.join('\n');
return [{ json: { statusText: text } }];

// План — з Кошторису (payment_schedule, записується лише при «затвердити» Кошторису)
const schedRows = ($('WR: Fetch Payment Schedule').first().json.rows) || [];
const hl = $('WR: Hard Logic Engine').first().json;
const pm = $('WR: Fetch Project Metrics Static').first().json;

function toNum(v){ if(v===null||v===undefined||v==='') return null; if(typeof v==='number') return v; const n=parseFloat(String(v).replace(/\s/g,'').replace(',','.')); return isNaN(n)?null:n; }
function fmtUAH(v){ return v===null?'—':Math.round(v).toLocaleString('uk-UA')+',00грн'; }
function fmtPct0(v){ return v===null?'—':Math.round(v*100)+'%'; }
function fmtPctDirect(v){ return v===null?'—':(Math.round(v*10)/10)+'%'; }
function fmtDate(v){ if(!v) return '—'; const d=new Date(v); if(isNaN(d)) return String(v); return d.toLocaleDateString('uk-UA',{day:'2-digit',month:'2-digit',year:'numeric'}); }
function probEmoji(p){ if(p===null) return ''; if(p<=5) return '🔴 '; if(p<=8) return '🟡 '; return '🟢 '; }
function fmtHrs(v){ return v===null?'—':(Math.round(v*10)/10)+'г'; }

const stageDefs = [
  {key:'МБР', label:'МБР'},
  {key:'ЕП', label:'ЕП'},
  {key:'П', label:'П'},
  {key:'Р', label:'Р'}
];

const etcPlanByStage = pm && pm.etc_plan_by_stage ? pm.etc_plan_by_stage : {};
const stageDataLive = pm && pm.stage_data ? pm.stage_data : {};
const moneyLogActs = $('WR: Fetch Money Log Acts').all().map(function(i){ return i.json; });

const stageAuto = stageDefs.map(function(s){
  var docRow = schedRows.find(function(g){ return g.s === s.key && g.e === 'документація'; });
  var actPlanRow = schedRows.find(function(g){ return g.s === s.key && g.e === 'акт'; });
  var deadlinePlanDate = docRow ? docRow.d : null;
  var actPlanDate = actPlanRow ? actPlanRow.d : null;
  var deadlineProb = actPlanRow ? toNum(actPlanRow.p) : null;
  var actRow = moneyLogActs.find(function(m){ return String(m['стадія']||'').trim() === s.key; });
  var actSigned = !!actRow;
  var etcPlan = toNum(etcPlanByStage[s.key]);
  var actualLive = toNum(stageDataLive[s.key] ? stageDataLive[s.key].actual_hours_live : null);
  var etcFact = (etcPlan!==null && actualLive!==null) ? Math.round((etcPlan-actualLive)*10)/10 : null;
  return {
    key: s.key, label: s.label,
    deadlinePlanDate: deadlinePlanDate, actPlanDate: actPlanDate, deadlineProb: deadlineProb, actSigned: actSigned,
    etcPlan: etcPlan, actualLive: actualLive, etcFact: etcFact
  };
});

const stagesAutoLines = stageAuto.map(function(s){
  return 'Стадія ' + s.label + ': ETC_план ' + fmtHrs(s.etcPlan) + ', Фактичний_час ' + fmtHrs(s.actualLive) +
    ', ETC_факт(=ETC_план−Фактичний_час, вже пораховано) ' + fmtHrs(s.etcFact) +
    ', Дедлайн_план (видача документації за Кошторисом) ' + fmtDate(s.deadlinePlanDate);
}).join('\n');

const etcTotalPlan = stageAuto.reduce(function(sum,s){ return sum + (s.etcPlan||0); }, 0);
const actualHoursTotal = toNum(pm ? pm.actual_hours : null);
const etcTotalFact = actualHoursTotal !== null ? Math.round((etcTotalPlan - actualHoursTotal) * 10) / 10 : null;
const rentPlan = toNum(pm ? pm.profitability_plan_pct : null);
const rentForecast = toNum(pm ? pm.profitability_forecast_pct : null);

const actsAutoLines = stageAuto.map(function(s){
  return 'Акт ' + s.label + ': ' + (s.actSigned ? '✅ (підписаний)' : (fmtDate(s.actPlanDate) + (s.deadlineProb!==null?' / '+s.deadlineProb+'/10':' / —')));
}).join('\n');
const firstUnpaidStage = stageAuto.find(function(s){ return !s.actSigned; });
const actProbabilityAuto = firstUnpaidStage ? firstUnpaidStage.deadlineProb : null;

const planItems = $('WR: Fetch This Week Plan').all().map(function(i){ return i.json; }).filter(function(i){ return i.item_number != null && i.item_number !== ''; });
const planItemsText = planItems.length ? planItems.map(function(i){ return i.item_number + '. ' + i.item_text; }).join('\n') : null;

const carryoverBlock = planItemsText ? (
  '\n\nПЛАН МИНУЛОГО ТИЖНЯ (потрібно уточнити статус, якщо ПМ ще не підтвердив у цьому повідомленні):\n' + planItemsText + '\n' +
  'ПРАВИЛО СТАТУСУ ПЛАНУ: якщо ПМ пише за номерами або узагальнено — розпізнай як item_statuses: масив {item_number, status: "done"|"not_done"}. Якщо ПМ ще НЕ підтвердив статус — постав про це одне пряме питання раніше за інші, item_statuses=null. Інакше item_statuses=null.\n' +
  'ВІЗУАЛ У ШАБЛОНІ (розділ 6, План на тиждень): пункти минулого тижня зі status="not_done" (або взагалі не підтверджені) переносяться в розділ 6 цього звіту з міткою 🔴 перед номером, за їх ОРИГІНАЛЬНИМ номером — без повторного передруку повного тексту пункту, лише номер+🔴+короткий заголовок. Пункти зі status="done" в розділ 6 НЕ переносяться.'
) : ('\n\nВАЖЛИВО: немає плану з минулого тижня — item_statuses ОБОВ’ЯЗКОВО null.');

