'2.1. Стадія МБР: [з довідки АВТО нижче: якщо "✅ (підписаний)" — виведи дослівно "✅ (підписаний)", інакше "ДАТА / N/10" (планова дата Акту і ймовірність за Кошторисом)]\n' +
'2.2. Стадія ЕП: [той же формат]\n' +
'2.3. Стадія П: [той же формат]\n' +
'2.4. Стадія Р: [той же формат]\n' +
'2.5. Ймовірність видачі документації (оцінка ПМ): N/10\n\n' +
'<b>3. КОМЕНТАРІ ПМ</b>\n[нумеровані пункти; якщо немає — "(дані ще не надано)"]\n\n' +
'<b>4. ПРОБЛЕМИ</b>\n[якщо є блокер — ПЕРШИМ пунктом "⛔ Блокер з ДД.ММ.РРРР: причина — що потрібно"; далі нумеровані пункти; якщо немає нічого — "(без зауважень)"]\n\n' +
'<b>5. ДОПОМОГА</b>\n[нумеровані пункти; якщо немає — "(не потрібно)"]\n\n' +
'<b>6. ПЛАН НА ТИЖДЕНЬ</b>\n[нумеровані пункти на НАСТУПНИЙ тиждень; невиконані/непідтверджені пункти минулого тижня — ОКРЕМИМИ рядками з міткою 🔴 перед номером (див. правило ВІЗУАЛ вище); якщо взагалі немає жодного пункту — "(дані ще не надано)"]\n\n' +
'--- ДОВІДКА АВТО-ДАНИХ (використовуй дослівно, не вигадуй інші числа) ---\n' +
'По стадіях (для 1.1-1.4.2):\n' + stagesAutoLines + '\n\n' +
'Блок АВТО для 2 (Акти по стадіях, з реального Money_Log — тип "акт_підписаний"):\n' + actsAutoLines + '\n\n' +
'ПРАВИЛА:\n- НЕ вигадуй дані, яких ПМ не називав.\n- Кожен рядок 1.1-1.4 ЗАВЖДИ має номер і назву стадії на початку.\n- Дати в тексті "message" (розділ 1: "Дедлайн X: план ДАТА / прогноз ДАТА"; розділ 2: "Стадія X: ДАТА / N/10") ЗАВЖДИ у форматі ДД.ММ.РРРР (наприклад 20.10.2026) — НІКОЛИ у форматі РРРР-ММ-ДД. Формат РРРР-ММ-ДД дозволений ТІЛЬКИ всередині JSON-поля deadline_forecast_stage, НІКОЛИ в самому тексті message.\n- Слова "ETC" тепер ДОЗВОЛЕНІ (частина канонічної назви ETC_план/ETC_факт/ETC_прогноз) — але тільки в цій формі, не як самостійне слово без префікса.\n- Слова "факт"/"фактична" щодо ГОТОВНОСТІ стадій (не ETC) ЗАБОРОНЕНІ в розділі 1 — тільки канонічні назви з глосарія вище.\n- Питання при process_data/show_draft дозволене коли: (a) не вистачає хоч одного з 6 пунктів чек-листу (стадії/ETC_прогноз/дедлайн/ймовірність документації/актуальність Актів/блокер), або (b) є активний план минулого тижня без підтвердження. При команді "фінал" з неповним чек-листом — СТАВ питання замість FINAL_REPORT.\n- НА КРОЦІ "ФІНАЛ" (коли tag=FINAL_REPORT) stage_readiness, etc_forecast_hours_stage, deadline_forecast_stage, doc_probability, blocker_types ОБОВ’ЯЗКОВО мають бути заповнені реальними значеннями, зібраними за ВСЮ розмову — це НЕ опціональні поля, вони йдуть в базу даних (крім елементів, які ПМ закрив як «відповіді нема» — вони в no_answer). act_probability — авто, див. вище.\n\n' +
'Формат виводу — ЛИШЕ JSON:\n{"tag":"DRAFT"|"FINAL_REPORT","message":"...","item_statuses":[{"item_number":N,"status":"done"|"not_done"}]|null,"plans_next_week":"..."|null,"stage_readiness":{"МБР":number,"ЕП":number,"П":number,"Р":number},"etc_forecast_hours_stage":{"МБР":number,"ЕП":number,"П":number,"Р":number},"deadline_forecast_stage":{"МБР":"YYYY-MM-DD","ЕП":"YYYY-MM-DD","П":"YYYY-MM-DD","Р":"YYYY-MM-DD"},"act_probability":number,"doc_probability":number,"problems_text":"..."|null,"help_text":"..."|null,"pm_comment_text":"..."|null,"blocker_types":["люди"|"гроші"|"замовник"|"інше"],"blocker_since":"YYYY-MM-DD"|null,"blocker_need":"..."|null,"readiness_gap_confirmed":true|false,"readiness_gap_note":"..."|null,"no_answer":["готовність:МБР"|"ETC:ЕП"|"дата:П"|"документація"|"план"|"блокер"]}';

return [{ json: { system_prompt: systemPrompt, payload: hl.payload, execution_mode: hl.execution_mode, project_id: hl.project_id } }];

const item = $input.first();
let raw = item.json.output ?? item.json.text ?? '';
if (typeof raw === 'string') raw = raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim();
let out;
try { out = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch(e) { out = { tag:'DRAFT', message: String(raw) }; }
const hl = $('WR: Hard Logic Engine').first().json;
let message = out.message || '';

const rawTag = out.tag || 'DRAFT';
let tag = (hl.execution_mode === 'generate_final' && rawTag === 'FINAL_REPORT') ? 'FINAL_REPORT' : 'DRAFT';

let plansNextWeek = out.plans_next_week || null;
if (!plansNextWeek) {
  const match = message.match(/<b>(?:2|6)\. ПЛАН НА ТИЖДЕНЬ<\/b>\n([\s\S]*?)(?=\n\n<b>|$)/);
  if (match) {
    const extracted = match[1].trim();
    if (extracted && extracted !== '(дані ще не надано)') {
      plansNextWeek = extracted.split('\n').map(function(l){
        return l.replace(/^\d+\.\d+\.\s*/, '').trim();
      }).filter(Boolean).join('\n');
    }
  }
}

function clampInt1to10(v){
  if (v === null || v === undefined || v === '') return null;
  var n = typeof v === 'number' ? v : parseFloat(String(v).replace(',', '.'));
  if (isNaN(n)) return null;
  n = Math.round(n);
  if (n < 1) n = 1;
  if (n > 10) n = 10;
  return n;
}
function cleanStageReadiness(obj){
  if (!obj || typeof obj !== 'object') return null;
  var allowedStages = ['МБР','ЕП','П','Р'];
  var out = {};
  var any = false;
  allowedStages.forEach(function(s){
    var v = obj[s];
    if (v === null || v === undefined || v === '') return;
    var n = typeof v === 'number' ? v : parseFloat(String(v).replace(',', '.').replace('%',''));
    if (isNaN(n)) return;
    if (n < 0) n = 0;
    if (n > 100) n = 100;
    out[s] = n;
    any = true;
  });
  return any ? out : null;
}
function cleanStageHours(obj){
  if (!obj || typeof obj !== 'object') return null;
  var allowedStages = ['МБР','ЕП','П','Р'];
  var out = {};
  var any = false;
  allowedStages.forEach(function(s){
    var v = obj[s];
    if (v === null || v === undefined || v === '') return;
    var n = typeof v === 'number' ? v : parseFloat(String(v).replace(',', '.'));
    if (isNaN(n) || n < 0) return;
    out[s] = n;
    any = true;
  });
  return any ? out : null;
}

const noAns = Array.isArray(out.no_answer) ? out.no_answer.map(function(x){ return String(x).trim(); }) : [];
const na = function(k){ return noAns.indexOf(k) >= 0; };
const stageReadiness = cleanStageReadiness(out.stage_readiness);
const etcForecastStage = cleanStageHours(out.etc_forecast_hours_stage);
const actProbability = clampInt1to10(out.act_probability);
const docProbability = clampInt1to10(out.doc_probability);
const problemsText = out.problems_text || null;
const helpText = out.help_text || null;
const pmCommentText = out.pm_comment_text || null;

// Блокер: {types:[...], since, need}; {types:[]} — немає; null — ПМ ще не відповів
const BLOCK_TYPES = ['люди','гроші','замовник','інше'];
let blocker = null;
if (Array.isArray(out.blocker_types)) {
  const types = out.blocker_types.map(function (t) { return String(t).trim().toLowerCase(); }).filter(function (t) { return BLOCK_TYPES.indexOf(t) >= 0; });
  const since = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(out.blocker_since || '')) ? String(out.blocker_since) : null;
  blocker = types.length ? { types: types, since: since, need: out.blocker_need ? String(out.blocker_need) : null } : { types: [] };
}

// БРИФ: фінал приймається тільки з обов'язковими відповідями (код, не рішення LLM)
if (tag === 'FINAL_REPORT') {
  const STG = ['МБР','ЕП','П','Р'];
  const dl = (out.deadline_forecast_stage && typeof out.deadline_forecast_stage === 'object') ? out.deadline_forecast_stage : {};
  const missing = [];
  STG.forEach(function (s) {
    const m = [];
    if ((!stageReadiness || stageReadiness[s] === undefined) && !na('готовність:' + s)) m.push('готовність %');
    if ((!etcForecastStage || etcForecastStage[s] === undefined) && !na('ETC:' + s)) m.push('скільки годин ще потрібно');
    if ((!dl[s] || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(dl[s]))) && !na('дата:' + s)) m.push('дата завершення');
    if (m.length) missing.push(s + ': ' + m.join(', '));
  });
  if (docProbability === null && !na('документація')) missing.push('ймовірність видачі документації (1–10)');
  if (!plansNextWeek && !na('план')) missing.push('план на наступний тиждень');
  if (!blocker && !na('блокер')) missing.push('чи є блокер (що зупиняє роботу; якщо нічого — «немає»)');
  else if (blocker && blocker.types.length && !blocker.since) missing.push('блокер: з якої дати проєкт стоїть');
  if (missing.length) {
    tag = 'DRAFT';
    message = '⚠️ Фінал не прийнято — бракує відповідей з брифу:' + String.fromCharCode(10) + missing.map(function (x) { return '• ' + x; }).join(String.fromCharCode(10)) + String.fromCharCode(10) + 'Додайте їх і натисніть «Фінал» ще раз.' + String.fromCharCode(10) + String.fromCharCode(10) + message;
  }
}

// «ВІДПОВІДІ НЕМА»: явний стан для елементів брифу (рядок у проблемах + у звіті; значення в БД не вигадуються)
const NA_LABELS = { 'документація': 'ймовірність видачі документації', 'план': 'план на наступний тиждень', 'блокер': 'чи є блокер' };
const naLines = noAns.map(function (k) {
  const m = /^(готовність|ETC|дата):(МБР|ЕП|П|Р)$/.exec(k);
  if (m) return (m[1] === 'готовність' ? 'готовність' : m[1] === 'ETC' ? 'ETC_прогноз' : 'дата завершення') + ' ' + m[2];
  return NA_LABELS[k] || null;
}).filter(Boolean);
let problemsOut = problemsText;
if (naLines.length) {
  const naText = '❓ Відповіді нема (ПМ): ' + naLines.join('; ');
  problemsOut = problemsText ? (problemsText + String.fromCharCode(10) + naText) : naText;
  message = message + String.fromCharCode(10) + String.fromCharCode(10) + naText;
}

// ПЕРЕВІРКА ГОТОВНОСТІ (код, не ШІ): оцінка ПМ vs за годинами = витрачено / (витрачено + ETC_прогноз)
const pmStatic = $('WR: Fetch Project Metrics Static').first().json || {};
const GAP_PP = (pmStatic.readiness_gap_pp !== null && pmStatic.readiness_gap_pp !== undefined && !isNaN(Number(pmStatic.readiness_gap_pp))) ? Number(pmStatic.readiness_gap_pp) : 20;
let sdLive = pmStatic.stage_data || {};
if (typeof sdLive === 'string') { try { sdLive = JSON.parse(sdLive); } catch (e) { sdLive = {}; } }
const NLc = String.fromCharCode(10);
const gaps = {};
if (stageReadiness && etcForecastStage) {
  ['МБР','ЕП','П','Р'].forEach(function (s) {
    const pmR = stageReadiness[s], etc = etcForecastStage[s];
    if (pmR === undefined || etc === undefined) return;
    const act = Number((sdLive[s] || {}).actual_hours_live) || 0;
    if (act + etc <= 0) return;
    const byHours = Math.round(act / (act + etc) * 100);
    if (Math.abs(pmR - byHours) >= GAP_PP) gaps[s] = { pm: pmR, hours: byHours, act: Math.round(act * 10) / 10, etc: etc };
  });
}
const gapStages = Object.keys(gaps);
const gapConfirmed = out.readiness_gap_confirmed === true || /підтверджу\S*\s+розбіжн|розбіжн\S*\s+підтвердж/i.test(String(hl.payload || ''));
const gapNote = out.readiness_gap_note ? String(out.readiness_gap_note) : null;
let readinessGap = null;
if (gapStages.length) {
  const gapLines = gapStages.map(function (s) { const g = gaps[s]; return '• ' + s + ': за оцінкою ' + g.pm + '%, за годинами ' + g.hours + '% (витрачено ' + g.act + ' год, за ETC_прогноз лишилось ' + g.etc + ' год)'; }).join(NLc);
  if (!gapConfirmed) {
    const ask = '⚖️ Готовність не збігається з годинами:' + NLc + gapLines + NLc + 'Перевірте оцінку готовності або ETC_прогноз і надішліть виправлені цифри. Якщо все правильно — напишіть «підтверджую розбіжність» і коротко чому: розбіжність буде зафіксована у звіті.';
    if (tag === 'FINAL_REPORT') { tag = 'DRAFT'; message = '⚠️ Фінал не прийнято.' + NLc + ask + NLc + NLc + message; }
    else { message = message + NLc + NLc + ask; }
  } else {
    gapStages.forEach(function (s) { if (gapNote) gaps[s].note = gapNote; });
    readinessGap = gaps;
    if (tag === 'FINAL_REPORT') message = message + NLc + NLc + '<b>⚖️ Розбіжність готовності (підтверджено ПМ)</b>' + NLc + gapLines + (gapNote ? NLc + 'Пояснення ПМ: ' + gapNote : '');
  }
}

return [{ json: {
  tag: tag,
  message: message,
  project_id: hl.project_id,
  item_statuses: out.item_statuses || null,
  plans_next_week: plansNextWeek,
  stage_readiness: stageReadiness,
  etc_forecast_stage: etcForecastStage,
  deadline_forecast_stage: (out.deadline_forecast_stage && typeof out.deadline_forecast_stage === 'object') ? out.deadline_forecast_stage : null,
  act_probability: actProbability,
  doc_probability: docProbability,
  problems_text: problemsOut,
  help_text: helpText,
  pm_comment_text: pmCommentText,
  blocker: blocker,
  readiness_gap: readinessGap
} }];

const item = $input.first();
const statuses = item.json.item_statuses || [];
const projectId = item.json.project_id;
const weekStart = $now.startOf('week').toFormat('yyyy-MM-dd');
if (!Array.isArray(statuses) || statuses.length === 0) return [];
return statuses.filter(function(s){ return s && s.item_number != null && s.status; }).map(function(s){
  return { json: { project_id: projectId, week_start: weekStart, item_number: s.item_number, status: s.status } };
});

const parsed = $input.first().json;
const projectId = parsed.project_id;
const plansNextWeekText = (parsed.plans_next_week || '').trim();
const itemStatuses = parsed.item_statuses || [];

const originalItems = $('WR: Fetch This Week Plan').all().map(function(i){ return i.json; }).filter(function(i){ return i.item_number != null; });
const statusMap = {};
itemStatuses.forEach(function(s){ if (s && s.item_number != null) statusMap[s.item_number] = s.status; });

const notDoneTexts = originalItems
  .filter(function(i){ return (statusMap[i.item_number] || i.status) === 'not_done'; })
  .map(function(i){ return i.item_text; });

const newLines = plansNextWeekText ? plansNextWeekText.split('\n').map(function(l){ return l.trim(); }).filter(Boolean) : [];
const newTexts = newLines.map(function(l){
  const m = l.match(/^\d+[\.\)]\s+(.+)$/);
  return m ? m[1].trim() : l;
});

const dedupedCarryover = notDoneTexts.filter(function(t){ return !newTexts.some(function(nt){ return nt.toLowerCase() === t.toLowerCase(); }); });
const combined = dedupedCarryover.concat(newTexts);

return [{ json: { project_id: projectId, combined_items: combined } }];

const item = $input.first();
const projectId = item.json.project_id;
const items = item.json.combined_items || [];
const nextWeekStart = $now.startOf('week').plus({ weeks: 1 }).toFormat('yyyy-MM-dd');
if (!items.length) return [];
return items.map(function(text, idx){
  return { json: { project_id: projectId, week_start: nextWeekStart, item_number: idx + 1, item_text: text } };
});

const item = $input.first();
let raw = item.json.output ?? item.json.text ?? '';
if (typeof raw === 'string') raw = raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,'').trim();
let out;
try { out = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch(e) { out = { tag:'DRAFT', message: String(raw) }; }
const hl = $('WR: Hard Logic Engine').first().json;
let message = out.message || '';
const rawTag = out.tag || 'DRAFT';
let tag = (hl.execution_mode === 'generate_import_final' && rawTag === 'FINAL_REPORT') ? 'FINAL_REPORT' : 'DRAFT';

function cleanTimeRows(rows) {
  if (!Array.isArray(rows)) return [];
  const allowedStages = ['МБР','ЕП','П','Р'];
  return rows.filter(function(r){ return r && r.date && allowedStages.includes(r.stage) && r.executor && r.hours != null; });
}
function cleanMoneyRows(rows) {
  if (!Array.isArray(rows)) return [];
  const allowedTypes = ['оплата_субпідряднику','надходження_від_замовника','акт_підписаний'];
  return rows.filter(function(r){ return r && r.date && r.counterparty && r.amount != null && allowedTypes.includes(r.type); });
}

// БРИФ: неповні рядки не відкидаються мовчки — фінал блокується з переліком
if (tag === 'FINAL_REPORT') {
  const NL = String.fromCharCode(10);
  const ST = ['МБР','ЕП','П','Р'];
  const TY = ['оплата_субпідряднику','надходження_від_замовника','акт_підписаний'];
  const problems = [];
  const badNum = function (v) { if (v === null || v === undefined || v === '') return true; const n = Number(String(v).replace(/\s/g, '').replace(',', '.')); return isNaN(n) || n <= 0; };
  (Array.isArray(out.time_rows) ? out.time_rows : []).forEach(function (r, i) {
    const m = [];
    if (!r || !r.date) m.push('дата');
    if (!r || ST.indexOf(r.stage) < 0) m.push('стадія (МБР/ЕП/П/Р)');
    if (!r || !r.executor) m.push('виконавець');
    if (!r || badNum(r.hours)) m.push('кількість годин');
    if (m.length) problems.push('Години, рядок ' + (i + 1) + ' (' + [r && r.date, r && r.executor, r && r.hours].filter(Boolean).join(', ') + '): бракує ' + m.join(', '));
  });
  (Array.isArray(out.money_rows) ? out.money_rows : []).forEach(function (r, i) {
    const m = [];
    if (!r || !r.date) m.push('дата');
    if (!r || TY.indexOf(r.type) < 0) m.push('тип (оплата субпідряднику / надходження від замовника / акт підписаний)');
    if (!r || !r.counterparty) m.push('контрагент');
    if (!r || badNum(r.amount)) m.push('сума');
    if (m.length) problems.push('Гроші, рядок ' + (i + 1) + ' (' + [r && r.date, r && r.counterparty, r && r.amount].filter(Boolean).join(', ') + '): бракує ' + m.join(', '));
  });
  const total = (Array.isArray(out.time_rows) ? out.time_rows.length : 0) + (Array.isArray(out.money_rows) ? out.money_rows.length : 0);
  if (total === 0) problems.push('немає жодного рядка годин чи грошей');
  if (problems.length) {
    tag = 'DRAFT';
    message = '⚠️ Фінал не прийнято — неповні дані:' + NL + problems.map(function (x) { return '• ' + x; }).join(NL) + NL + 'Доповніть і натисніть «Фінал» ще раз. Нічого не записано.';
  }
}

return [{ json: {
  tag: tag,
  message: message,
  project_id: hl.project_id,
  time_rows: cleanTimeRows(out.time_rows),
  money_rows: cleanMoneyRows(out.money_rows)
} }];

const item = $input.first().json;
const rows = item.time_rows || [];
return rows.map(function(r){
  return { json: {
    ProjectID: item.project_id,
    Дата: r.date,
    Стадія: r.stage,
    Виконавець: r.executor,
    'Завдання / розділ': r.task_section || '',
    Години: r.hours,
    Статус: 'confirmed'
  } };
});

const item = $input.first().json;
const rows = item.money_rows || [];
return rows.map(function(r){
  return { json: {
    ProjectID: item.project_id,
    Дата: r.date,
    Стадія: r.stage || '',
    Контрагент: r.counterparty,
