  const plannedHours = toNum(m.planned_hours);
  const actualHours = toNum(m.actual_hours);
  const etcTotal = toNum(m.etc_forecast_total_hours);
  // Години до кінця (факт + ETC прогноз) відносно бюджету годин з Кошторису; >100% — перевищення
  let eacHoursPct = null;
  if (plannedHours && actualHours !== null && etcTotal !== null) {
    eacHoursPct = Math.round(((actualHours + etcTotal) / plannedHours) * 1000) / 10;
  }
  const sd = m.stage_data || {};
  const stageForecast = {};
  numberedStages.forEach(function(s){ stageForecast[s] = toNum((sd[s]||{}).readiness_forecast); });
  return {
    label: 'Сьогодні (Data Total)',
    isToday: true,
    m1: { plan: toNum(m.profitability_plan_pct), forecast: toNum(m.profitability_forecast_pct) },
    m2: { plan: (plannedHours!=null && actualHours!=null) ? Math.round((plannedHours-actualHours)*10)/10 : null, forecast: etcTotal },
    m3: { plan: 100, forecast: eacHoursPct },
    stages: stageForecast,
    m7: { date: m.nearest_act_date||null, prob: toNum(m.nearest_act_probability) },
    m8: { date: m.nearest_doc_deadline||null, prob: toNum(m.doc_issuance_probability) },
    m9: { plan: 1, forecast: toNum(m.cpi_classic_evm) },
    plan: null, problems: null, help: null, comment: null, pmStages: null
  };
}

