const crypto = require('crypto');
// Перевірка входу без токена: підпис Telegram (Ed25519, публічний ключ Telegram) + номер бота (не секрет)
const BOT_ID = '8813476306';
const TG_PUBLIC_KEY_HEX = 'e7bf03a2fa4602af4580703d88dda5bb59f32ed8b02a56c187fe7d34caed242d';
const MAX_AGE_SECONDS = 86400;
// Доступ: тільки люди з цього списку (Telegram id через кому, у лапках)
const ALLOWED = ['304884647'];
const initData = ($json.query && $json.query.initData) ? $json.query.initData : '';
if (!initData) { return [{ json: { valid: false, reason: 'no_init_data' } }]; }
let signature = null; let authDateStr = null; const kvPairs = [];
for (const raw of initData.split('&')) {
  const idx = raw.indexOf('=');
  if (idx === -1) continue;
  const key = raw.substring(0, idx);
  const rawValue = raw.substring(idx + 1);
  let value; try { value = decodeURIComponent(rawValue); } catch (e) { value = rawValue; }
  if (key === 'hash') { continue; }
  if (key === 'signature') { signature = value; continue; }
  kvPairs.push(key + '=' + value);
  if (key === 'auth_date') { authDateStr = value; }
}
if (!signature) { return [{ json: { valid: false, reason: 'no_signature' } }]; }
kvPairs.sort();
const NL = String.fromCharCode(10);
const dataCheckString = BOT_ID + ':WebAppData' + NL + kvPairs.join(NL);
let signatureValid = false;
try {
  const publicKey = crypto.createPublicKey({ key: Buffer.from('302a300506032b6570032100' + TG_PUBLIC_KEY_HEX, 'hex'), format: 'der', type: 'spki' });
  const sig = Buffer.from(signature.replace(/-/g, '+').replace(/_/g, '/'), 'base64');
  signatureValid = crypto.verify(null, Buffer.from(dataCheckString), publicKey, sig);
} catch (e) { signatureValid = false; }
let fresh = true;
if (authDateStr) { const ageSeconds = (Date.now() / 1000) - parseInt(authDateStr, 10); fresh = ageSeconds >= 0 && ageSeconds < MAX_AGE_SECONDS; }
let userId = null;
for (const kv of kvPairs) { if (kv.startsWith('user=')) { try { userId = String(JSON.parse(kv.slice(5)).id); } catch (e) {} } }
const member = !!userId && ALLOWED.includes(userId);
return [{ json: { valid: signatureValid && fresh && member, hashValid: signatureValid, fresh: fresh, member: member } }];

const snapshots = $input.all().map(function(i){ return i.json; });

const byProject = {};
const weeksSet = new Set();
snapshots.forEach(function(s){
  const pid = s.project_id;
  const week = s.week_start;
  weeksSet.add(week);
  if (!byProject[pid]) byProject[pid] = {};
  const readiness = s['готовність_pct'] || {};
  const etcStage = s['залишок_прогноз_по_стадіях'] || null;
  let etcTotal = null;
  if (etcStage && typeof etcStage === 'object') {
    etcTotal = Object.values(etcStage).reduce(function(sum, v){ return sum + (Number(v)||0); }, 0);
  } else if (s['залишок_прогноз_год'] != null) {
    etcTotal = Number(s['залишок_прогноз_год']);
  }
  byProject[pid][week] = {
    readiness_MBR: readiness['МБР'] != null ? readiness['МБР'] : '',
    readiness_EP: readiness['ЕП'] != null ? readiness['ЕП'] : '',
    readiness_P: readiness['П'] != null ? readiness['П'] : '',
    readiness_R: readiness['Р'] != null ? readiness['Р'] : '',
    etc_total_h: etcTotal != null ? Math.round(etcTotal*10)/10 : '',
    act_prob: s['ймовірність_акту'] != null ? s['ймовірність_акту'] : '',
    doc_prob: s['ймовірність_документації'] != null ? s['ймовірність_документації'] : ''
  };
});

const allProjects = Object.keys(byProject).sort(function(a,b){ return String(a).localeCompare(String(b),'uk',{numeric:true}); });
const weeks = Array.from(weeksSet).sort();

const rows = allProjects.map(function(pid){
  const row = { project_id: pid };
  weeks.forEach(function(w){
    const cell = (byProject[pid] && byProject[pid][w]) || {};
    row[w + '_МБР_%'] = cell.readiness_MBR;
    row[w + '_ЕП_%'] = cell.readiness_EP;
    row[w + '_П_%'] = cell.readiness_P;
    row[w + '_Р_%'] = cell.readiness_R;
    row[w + '_ETC_прогноз_год'] = cell.etc_total_h;
    row[w + '_Ймовірність_акту'] = cell.act_prob;
    row[w + '_Ймовірність_документації'] = cell.doc_prob;
  });
  return { json: row };
});

if (rows.length === 0) {
  rows.push({ json: { project_id: 'немає даних' } });
}

return rows;

